function withinTolerance(expectedCents, receivedCents, tol = TOLERANCE_CENTS) {
  return Math.abs(expectedCents - receivedCents) <= tol;
}

module.exports = { TOLERANCE_CENTS, toCents, parseRandAmount, formatZar, withinTolerance };

};
