  const s = String(v === undefined || v === null ? '' : v).trim();
  if (!/^\d{1,6}$/.test(s)) throw new TypeError('broker_ref must be 1-6 digits (brokers.billing_ref), got ' + JSON.stringify(s));
  return s.padStart(4, '0');
